package ledger

import (
	"errors"
	"fmt"
	"sort"
	"strconv"
	"strings"
)

// Refactor log:
//   - Replaced the hand-rolled selection sort with sort.Slice (date, then
//     description, then change).
//   - Dropped the goroutine/channel fan-out for formatting rows; a plain loop
//     is simpler and the output is deterministic.
//   - Split formatting into small helpers: header, formatDate,
//     truncateDescription, formatAmount, groupDigits.
//   - Validate currency and locale once up front instead of per-row.
//   - Use fmt.Sprintf field widths instead of manual strings.Repeat padding.
//   - Input slice is copied before sorting, so callers' slice is never mutated.

// Entry is a single ledger transaction.
type Entry struct {
	Date        string // "Y-m-d"
	Description string
	Change      int // in cents
}

var (
	errInvalidCurrency = errors.New("invalid currency")
	errInvalidLocale   = errors.New("invalid locale")
	errInvalidDate     = errors.New("invalid date")
)

// FormatLedger renders entries as a fixed-width table for the given currency
// ("USD" or "EUR") and locale ("en-US" or "nl-NL").
func FormatLedger(currency string, locale string, entries []Entry) (string, error) {
	if currency != "USD" && currency != "EUR" {
		return "", errInvalidCurrency
	}
	if locale != "en-US" && locale != "nl-NL" {
		return "", errInvalidLocale
	}

	sorted := make([]Entry, len(entries))
	copy(sorted, entries)
	sort.Slice(sorted, func(i, j int) bool {
		if sorted[i].Date != sorted[j].Date {
			return sorted[i].Date < sorted[j].Date
		}
		if sorted[i].Description != sorted[j].Description {
			return sorted[i].Description < sorted[j].Description
		}
		return sorted[i].Change < sorted[j].Change
	})

	var b strings.Builder
	b.WriteString(header(locale))
	for _, e := range sorted {
		line, err := formatEntry(currency, locale, e)
		if err != nil {
			return "", err
		}
		b.WriteString(line)
	}
	return b.String(), nil
}

// header returns the table header line for the given locale.
func header(locale string) string {
	if locale == "nl-NL" {
		return "Datum      | Omschrijving              | Verandering\n"
	}
	return "Date       | Description               | Change\n"
}

// formatEntry renders a single ledger row.
func formatEntry(currency, locale string, e Entry) (string, error) {
	date, err := formatDate(locale, e.Date)
	if err != nil {
		return "", err
	}
	return fmt.Sprintf("%-10s | %-25s | %13s\n",
		date, truncateDescription(e.Description), formatAmount(currency, locale, e.Change))
}

// formatDate validates the "Y-m-d" date and renders it for the locale.
func formatDate(locale, date string) (string, error) {
	if len(date) != 10 || date[4] != '-' || date[7] != '-' {
		return "", errInvalidDate
	}
	year, month, day := date[0:4], date[5:7], date[8:10]
	if locale == "nl-NL" {
		return day + "-" + month + "-" + year, nil
	}
	return month + "/" + day + "/" + year, nil
}

// truncateDescription shortens descriptions longer than 25 characters.
func truncateDescription(desc string) string {
	if len(desc) > 25 {
		return desc[:22] + "..."
	}
	return desc
}

// formatAmount renders a cent amount in the locale's number style.
func formatAmount(currency, locale string, change int) string {
	symbol := currencySymbol(currency)
	negative := change < 0
	if negative {
		change = -change
	}
	dollars := groupDigits(strconv.Itoa(change/100), thousandsSep(locale))
	cents := change % 100

	if locale == "nl-NL" {
		sign := " "
		if negative {
			sign = "-"
		}
		return fmt.Sprintf("%s %s%s%02d%s", symbol, dollars, decimalSep(locale), cents, sign)
	}
	if negative {
		return fmt.Sprintf("(%s%s%s%02d)", symbol, dollars, decimalSep(locale), cents)
	}
	return fmt.Sprintf("%s%s%s%02d ", symbol, dollars, decimalSep(locale), cents)
}

func currencySymbol(currency string) string {
	if currency == "EUR" {
		return "€"
	}
	return "$"
}

func thousandsSep(locale string) string {
	if locale == "nl-NL" {
		return "."
	}
	return ","
}

func decimalSep(locale string) string {
	if locale == "nl-NL" {
		return ","
	}
	return "."
}

// groupDigits inserts sep every three digits from the right, e.g. 1234567 -> "1.234.567".
func groupDigits(s, sep string) string {
	if len(s) <= 3 {
		return s
	}
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if i > 0 && (len(s)-i)%3 == 0 {
			b.WriteString(sep)
		}
		b.WriteByte(s[i])
	}
	return b.String()
}

